<?php

namespace Database\Seeders;

use App\Enums\DocumentStatus;
use App\Models\Department;
use App\Models\Document;
use App\Models\DocumentEvent;
use App\Models\PurchaseOrder;
use App\Models\Setting;
use App\Models\User;
use App\Services\DocumentProcessor;
use App\Services\DocumentWorkflow;
use App\Services\Samples\SampleInvoices;
use Illuminate\Database\Seeder;
use Illuminate\Support\Facades\File;

class DatabaseSeeder extends Seeder
{
    /**
     * Demo data. Every document is a synthetic invoice generated by SampleInvoices and processed
     * by the real pipeline with the demo rule parser, so the records are authentic demo output
     * and are labelled as such in the UI.
     */
    public function run(): void
    {
        // Seed data must never call a paid API, whatever .env says.
        config(['docai.provider' => 'demo']);

        $admin = User::updateOrCreate(['email' => 'admin@ledgerly.test'], ['name' => 'Amara Okafor', 'role' => User::ROLE_ADMIN, 'password' => 'password']);
        $reviewer = User::updateOrCreate(['email' => 'reviewer@ledgerly.test'], ['name' => 'Daniel Reyes', 'role' => User::ROLE_REVIEWER, 'password' => 'password']);
        User::updateOrCreate(['email' => 'viewer@ledgerly.test'], ['name' => 'Priya Nair', 'role' => User::ROLE_VIEWER, 'password' => 'password']);

        if (Document::exists()) {
            $this->command?->info('Documents already exist; skipping demo documents.');

            return;
        }

        $this->seedWorkspace($admin);

        $samples = storage_path('app/samples');
        File::deleteDirectory($samples);
        $paths = SampleInvoices::writeAll($samples);

        $departments = collect([
            ['IT & Systems', 'IT', 'CC-4100', $reviewer, '6100-IT'],
            ['Operations', 'OPS', 'CC-2200', $admin, '5200-OPS'],
            ['Finance', 'FIN', 'CC-1000', $reviewer, '6400-FIN'],
            ['Marketing', 'MKT', 'CC-3300', $admin, '6300-MKT'],
        ])->map(fn ($d) => [Department::updateOrCreate(['code' => $d[1]], ['name' => $d[0], 'cost_center' => $d[2], 'manager_id' => $d[3]->id, 'active' => true]), $d[4]]);

        $workflow = app(DocumentWorkflow::class);
        $processor = app(DocumentProcessor::class);
        $definitions = SampleInvoices::definitions();
        $total = count($paths);

        foreach ($paths as $i => $path) {
            $uploader = $i % 3 === 0 ? $admin : $reviewer;
            $document = $workflow->importFromPath($path, basename($path), $uploader);
            $processor->process($document);

            // Spread the history over the last three weeks so charts and timelines look lived-in.
            $offsets = [19, 18, 18, 16, 14, 13, 13, 12, 9, 8, 8, 8, 5, 3, 2, 0];
            $daysAgo = $offsets[$i] ?? 0;
            $created = now()->subDays($daysAgo)->setTime(9 + ($i % 7), 10 + ($i * 7) % 50);
            $document->refresh();
            [$department, $glCode] = $departments[$i % $departments->count()];
            $document->forceFill(['created_at' => $created, 'processed_at' => $created->copy()->addSeconds(4), 'department_id' => $department->id, 'gl_code' => $glCode])->saveQuietly();
            $this->retimeEvents($document, $created);

            // A realistic mix of review outcomes.
            $name = $definitions[$i]['file'];
            if (in_array($document->status, [DocumentStatus::Ready, DocumentStatus::NeedsReview], true) && $document->errorCount() === 0 && $i % 4 !== 3) {
                $document->refresh();
                $workflow->approve($document, $reviewer);
                $document->refresh()->forceFill(['reviewed_at' => $created->copy()->addHours(3)])->saveQuietly();
            }
            if (str_starts_with($name, 'DUPLICATE-')) {
                $workflow->reject($document->refresh(), $reviewer, 'Duplicate of INV-2026-0412 already on file.');
                $document->refresh()->forceFill(['reviewed_at' => $created->copy()->addHours(2)])->saveQuietly();
            }
            $this->retimeEvents($document->refresh(), $created);
        }

        $this->seedCollaboration($admin, $reviewer);

        DocumentEvent::whereNull('document_id')->delete();
        $this->command?->info(count($paths).' demo documents created. Sign in with admin@ledgerly.test / password.');
    }

    /** Company details, approval limit, a generated logo and a small purchase-order register. */
    private function seedWorkspace(User $admin): void
    {
        Setting::put('company_name', 'Harbourview Retail Group');
        Setting::put('company_legal_name', 'Harbourview Retail Group Ltd');
        Setting::put('company_address', "Harbourview House, 3 Quay Road\nLiverpool L3 1BP, United Kingdom");
        Setting::put('company_tax_id', 'GB 601 4412 77');
        Setting::put('approval_threshold', 5000);
        Setting::put('require_po', false);

        // A simple generated mark so the logo feature is visible in the demo (replace it under Settings).
        if (function_exists('imagecreatetruecolor')) {
            $img = imagecreatetruecolor(256, 256);
            imagesavealpha($img, true);
            $bg = imagecolorallocate($img, 36, 91, 84);
            $paper = imagecolorallocate($img, 245, 242, 235);
            $brass = imagecolorallocate($img, 196, 154, 63);
            imagefilledrectangle($img, 0, 0, 255, 255, $bg);
            imagefilledpolygon($img, [48, 176, 128, 56, 208, 176], $paper);
            imagefilledrectangle($img, 104, 132, 152, 176, $bg);
            imagefilledrectangle($img, 48, 192, 208, 204, $brass);
            ob_start();
            imagepng($img);
            $png = ob_get_clean();
            $path = 'branding/logo-demo.png';
            \Illuminate\Support\Facades\Storage::disk('local')->put($path, $png);
            Setting::put('logo_path', $path);
        }

        $orders = [
            ['PO-88412', 'Northwind Freight Ltd', 'GBP', 2500.00, '2026-08-24', 'open'],
            ['PO-77001', 'Atlas Office Supplies Inc.', 'USD', 1600.00, '2026-08-30', 'open'],
            ['PO-BD-3310', 'Harbor & Vine Catering Co.', 'USD', 1700.00, '2026-09-26', 'open'],
            ['PO-HV-2204', 'Solstice Print & Packaging Ltd', 'GBP', 2100.00, '2026-09-20', 'closed'],
            ['PO-GF-5521', 'Greenfield Facilities Management LLC', 'USD', 2000.00, '2026-10-01', 'open'],
            ['PO-BD-3322', 'Ridgeway Tools & Hardware Inc.', 'USD', 1500.00, '2026-10-05', 'open'],
            ['PO-HV-3001', 'Tidewater Marine Supply Co.', 'GBP', 1000.00, '2026-10-12', 'open'],
        ];
        foreach ($orders as [$number, $supplier, $currency, $total, $issued, $status]) {
            PurchaseOrder::create(['po_number' => $number, 'supplier_name' => $supplier, 'currency' => $currency, 'total' => $total, 'issued_on' => $issued, 'status' => $status, 'created_by' => $admin->id]);
        }
    }

    /** A few assignments and notes so those features are visible straight away. */
    private function seedCollaboration(User $admin, User $reviewer): void
    {
        $workflow = app(DocumentWorkflow::class);
        foreach (['Bluepeak' => [$reviewer, 'Supplier confirmed by phone that the printed total is a typo. Awaiting a corrected PDF.'], 'Ridgeway' => [$admin, 'Line items match the delivery note. Subtotal on the invoice looks wrong.'], 'Fleetline' => [$reviewer, null]] as $supplier => [$person, $note]) {
            $document = Document::where('supplier_name', 'like', "{$supplier}%")->first();
            if (! $document) {
                continue;
            }
            $workflow->assign($document, $person, $admin);
            if ($note) {
                $workflow->comment($document, $person, $note);
            }
            $this->retimeEvents($document->refresh(), $document->created_at);
        }
    }

    /** Re-stamps a document's timeline so events sit just after the (backdated) upload time. */
    private function retimeEvents(Document $document, \Illuminate\Support\Carbon $created): void
    {
        $document->events()->reorder('id')->get()->each(function (DocumentEvent $event, int $n) use ($created) {
            $event->forceFill(['created_at' => $created->copy()->addSeconds($n * 2 + ($event->type === 'approved' || $event->type === 'rejected' ? 7200 : 0))])->save();
        });
    }
}
